SELECT CASE WHEN YEAR(end_date) < 2024 THEN 'before_2024' WHEN YEAR(end_date) = 2024 THEN '2024' ELSE 'after_2024' END AS end_cohort, CASE WHEN monthly_fee >= 222 THEN 'high' WHEN monthly_fee >= 59 THEN 'mid' ELSE 'low' END AS monthly_fee_bucket, COUNT(monthly_fee) AS monthly_fee_count, ROUND(STDDEV(monthly_fee), 2) AS stddev_monthly_fee, AVG(monthly_fee) AS avg_monthly_fee FROM subscriptions GROUP BY CASE WHEN YEAR(end_date) < 2024 THEN 'before_2024' WHEN YEAR(end_date) = 2024 THEN '2024' ELSE 'after_2024' END, CASE WHEN monthly_fee >= 222 THEN 'high' WHEN monthly_fee >= 59 THEN 'mid' ELSE 'low' END
